# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_label_after_rounding(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        spans = [Span(15, 45)]
        self.assertEqual(
            round_spans(spans, 30), ["00:30-01:00 (0h 30m)"]
        )

    def test_many_spans(self):
        spans = [Span(0, 60), Span(61, 119)]
        self.assertEqual(
            round_spans(spans, 30),
            ["00:00-01:00 (1h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_bad_steps(self):
        for step in (0, -5, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
